import { Prisma } from '@prisma/client'

export async function topUsers(limit: number) {
  return prisma.$queryRaw<Array<{ id: number; total: bigint }>>`
    SELECT user_id AS id, COUNT(*) AS total
    FROM ${Prisma.raw('{{table}}')}
    GROUP BY user_id
    ORDER BY total DESC
    LIMIT ${limit}
  `
}
